"""Offline tests for growthkit.report (growth-reports/ output, sidecar, history).

Every test works in a fresh temporary folder that becomes the current
working directory, because reports are written relative to the cwd.

Run from the repo root:
    python3 -m unittest discover -s tests -t .
"""

import contextlib
import io
import json
import os
import subprocess
import sys
import tempfile
import unittest

from tests import _paths
from growthkit import report  # noqa: E402

EXPECTED_FOOTER = (
    "---\n"
    "*Report generated by landing-page-cro | SaaS Growth Marketing Skills*\n"
    "*GitHub: github.com/ekinciio/saas-growth-marketing-skills*\n"
)


class InTempDir(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.old_cwd = os.getcwd()
        os.chdir(self.tmp.name)
        self.addCleanup(os.chdir, self.old_cwd)

    def read(self, path):
        with open(path, encoding="utf-8") as handle:
            return handle.read()


class NamingTests(unittest.TestCase):
    def test_footer_matches_the_skill_convention(self):
        self.assertEqual(report.footer("landing-page-cro"), EXPECTED_FOOTER)

    def test_slugify(self):
        cases = {
            "Acme Kafe & Co.": "acme-kafe-co",
            "\u0130stanbul \u00c7i\u00e7ek\u00e7isi": "istanbul-cicekcisi",
            "Joe's Pizza NYC": "joe-s-pizza-nyc",
            "---": "",
        }
        for text, expected in cases.items():
            with self.subTest(text=text):
                self.assertEqual(report.slugify(text), expected)
        self.assertEqual(len(report.slugify("a" * 200)), 60)

    def test_subject_slug(self):
        cases = {
            "https://www.notion.com/": "notion-com",
            "https://notion.com": "notion-com",
            "linear.app/pricing": "linear-app-pricing",
            "https://cal.com/pricing?ref=x#top": "cal-com-pricing",
            "Acme Coffee, Austin": "acme-coffee-austin",
            "": "report",
        }
        for subject, expected in cases.items():
            with self.subTest(subject=subject):
                self.assertEqual(report.subject_slug(subject), expected)

    def test_report_paths(self):
        paths = report.report_paths("landing-page-cro", "https://www.notion.com", "2026-10-24", base_dir="/x")
        self.assertEqual(paths["markdown"], os.path.join("/x", "growth-reports",
                                                          "2026-10-24-landing-page-cro-notion-com.md"))
        self.assertTrue(paths["json"].endswith("2026-10-24-landing-page-cro-notion-com.json"))
        with self.assertRaises(ValueError):
            report.report_paths("x", "y", "24/10/2026")
        with self.assertRaises(ValueError):
            report.report_paths("x", "y", "2026-02-30")
        with self.assertRaises(ValueError):
            report.report_paths("!!!", "y", "2026-10-24")


class WriteReportTests(InTempDir):
    def test_first_run_creates_private_folder_sidecar_and_footer(self):
        saved = report.write_report(
            "landing-page-cro", "https://www.notion.com", "# CRO audit\n\nScore: 72/100\n",
            data={"scores": {"total": 72}}, date="2026-10-24")
        md = os.path.join("growth-reports", "2026-10-24-landing-page-cro-notion-com.md")
        self.assertEqual(saved["markdown_path"], md)
        self.assertEqual(self.read(os.path.join("growth-reports", ".gitignore")), "*\n")
        text = self.read(md)
        self.assertTrue(text.startswith("# CRO audit"))
        self.assertTrue(text.endswith(EXPECTED_FOOTER))
        self.assertEqual(text.count("Report generated by"), 1)
        self.assertIn("## Change since last run\n\nFirst run for this subject.", text)
        sidecar = json.loads(self.read(saved["json_path"]))
        self.assertEqual(sidecar["report"]["skill"], "landing-page-cro")
        self.assertEqual(sidecar["report"]["slug"], "notion-com")
        self.assertEqual(sidecar["report"]["toolkit_version"], "2.0.0")
        self.assertIsNone(sidecar["report"]["previous_run"])
        self.assertEqual(sidecar["data"], {"scores": {"total": 72}})
        self.assertIsNone(saved["previous_run"])

    def test_existing_gitignore_is_left_alone(self):
        os.makedirs("growth-reports")
        with open(os.path.join("growth-reports", ".gitignore"), "w", encoding="utf-8") as handle:
            handle.write("*.json\n")
        report.write_report("x", "y", "body", date="2026-10-24")
        self.assertEqual(self.read(os.path.join("growth-reports", ".gitignore")), "*.json\n")

    def test_second_run_compares_with_the_previous_run(self):
        report.write_report("geo-seo-auditor", "linear.app",
                            "# GEO\n", data={"scores": {"total": 60, "schema": 4}, "llms_txt": False,
                                             "pages": ["a"], "status": "ok"},
                            date="2026-09-24")
        saved = report.write_report("geo-seo-auditor", "https://linear.app/",
                                    "# GEO\n", data={"scores": {"total": 68, "schema": 4}, "llms_txt": True,
                                                     "pages": ["a", "b"], "status": "partial"},
                                    date="2026-10-24")
        self.assertEqual(saved["previous_run"]["date"], "2026-09-24")
        changes = {c["path"]: c for c in saved["changes"]}
        self.assertEqual(set(changes), {"scores.total", "llms_txt"})  # lists and meta keys ignored
        self.assertEqual(changes["scores.total"]["delta"], 8)
        self.assertIsNone(changes["llms_txt"]["delta"])
        text = self.read(saved["markdown_path"])
        self.assertIn("Previous run: 2026-09-24", text)
        self.assertIn("| scores.total | 60 | 68 | +8 |", text)
        self.assertIn("| llms_txt | no | yes | changed |", text)
        self.assertLess(text.index("## Change since last run"), text.index("---\n*Report generated by"))
        sidecar = json.loads(self.read(saved["json_path"]))
        self.assertEqual(sidecar["report"]["previous_run"], "2026-09-24")
        self.assertEqual(len(sidecar["changes_since_last_run"]), 2)

    def test_no_changes(self):
        report.write_report("s", "acme.test", "a", data={"score": 1}, date="2026-09-01")
        saved = report.write_report("s", "acme.test", "a", data={"score": 1}, date="2026-10-01")
        self.assertIn("No tracked values changed since 2026-09-01.", self.read(saved["markdown_path"]))

    def test_previous_without_sidecar(self):
        os.makedirs("growth-reports")
        with open(os.path.join("growth-reports", "2026-09-01-s-acme-test.md"), "w", encoding="utf-8") as handle:
            handle.write("old report")
        saved = report.write_report("s", "acme.test", "new", data={"score": 1}, date="2026-10-01")
        self.assertIn("has no JSON sidecar", self.read(saved["markdown_path"]))

    def test_same_day_rerun_overwrites_and_compares_with_an_earlier_day(self):
        report.write_report("s", "acme.test", "v1", data={"score": 1}, date="2026-09-01")
        report.write_report("s", "acme.test", "v2", data={"score": 2}, date="2026-10-01")
        saved = report.write_report("s", "acme.test", "v3", data={"score": 3}, date="2026-10-01")
        self.assertEqual(saved["previous_run"]["date"], "2026-09-01")
        self.assertEqual(saved["changes"][0]["delta"], 2)
        files = sorted(os.listdir("growth-reports"))
        self.assertEqual(files, [".gitignore", "2026-09-01-s-acme-test.json", "2026-09-01-s-acme-test.md",
                                 "2026-10-01-s-acme-test.json", "2026-10-01-s-acme-test.md"])

    def test_previous_run_matches_skill_and_subject_exactly(self):
        report.write_report("s", "acme.test/pricing", "x", data={"a": 1}, date="2026-09-01")
        report.write_report("other", "acme.test", "x", data={"a": 1}, date="2026-09-01")
        os.makedirs(os.path.join("growth-reports", ".cache"), exist_ok=True)
        self.assertIsNone(report.find_previous_run("s", "acme.test", before="2026-10-01"))
        self.assertEqual(report.find_previous_run("s", "acme.test/pricing")["date"], "2026-09-01")

    def test_ambiguous_file_name_is_rejected_by_sidecar_meta(self):
        # skill "geo" + subject "seo-auditor-acme-test" and skill "geo-seo-auditor"
        # + subject "acme-test" produce the same file name.
        report.write_report("geo-seo-auditor", "acme.test", "x", data={"a": 1}, date="2026-09-01")
        self.assertIsNone(report.find_previous_run("geo", "seo-auditor-acme-test", before="2026-10-01"))
        self.assertIsNotNone(report.find_previous_run("geo-seo-auditor", "acme.test", before="2026-10-01"))

    def test_existing_footer_and_change_section_are_not_duplicated(self):
        body = "# R\n\n## Change since last run\n\nWritten by the model.\n\n" + report.footer("s")
        saved = report.write_report("s", "acme.test", body, data={}, date="2026-10-01")
        text = self.read(saved["markdown_path"])
        self.assertEqual(text.count("Report generated by"), 1)
        self.assertEqual(text.count("## Change since last run"), 1)
        self.assertIn("Written by the model.", text)

    def test_base_dir_and_no_change_section(self):
        with tempfile.TemporaryDirectory() as other:
            saved = report.write_report("s", "acme.test", "x", date="2026-10-01", base_dir=other,
                                        add_change_section=False)
            self.assertTrue(os.path.isabs(saved["markdown_path"]))
            text = self.read(saved["markdown_path"])
            self.assertNotIn("Change since last run", text)
            self.assertFalse(os.path.exists("growth-reports"))

    def test_compare_paths_limits_the_table(self):
        report.write_report("s", "acme.test", "x", data={"a": 1, "b": 1}, date="2026-09-01")
        saved = report.write_report("s", "acme.test", "x", data={"a": 2, "b": 2}, date="2026-10-01",
                                    compare_paths=["b"])
        self.assertEqual([c["path"] for c in saved["changes"]], ["b"])


class DiffTests(unittest.TestCase):
    def test_diff_data(self):
        changes = report.diff_data({"a": {"b": 1.5}, "gone": 1, "tool": "x"},
                                   {"a": {"b": 2.0}, "new": "yes", "tool": "y"})
        by_path = {c["path"]: c for c in changes}
        self.assertEqual(by_path["a.b"]["delta"], 0.5)
        self.assertEqual(by_path["new"]["previous"], None)
        self.assertEqual(by_path["gone"]["current"], None)
        self.assertNotIn("tool", by_path)

    def test_limit(self):
        before = {"k%d" % i: i for i in range(50)}
        after = {"k%d" % i: i + 1 for i in range(50)}
        self.assertEqual(len(report.diff_data(before, after, limit=10)), 10)


class CommandLineTests(InTempDir):
    def run_main(self, *argv):
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = report.main(list(argv))
        return code, out.getvalue(), err.getvalue()

    def test_save_previous_and_path(self):
        with open("draft.md", "w", encoding="utf-8") as handle:
            handle.write("# Draft\n")
        with open("facts.json", "w", encoding="utf-8") as handle:
            json.dump({"score": 5}, handle)
        code, out, _ = self.run_main("save", "--skill", "pricing-analyzer", "--subject", "https://acme.test",
                                     "--markdown", "draft.md", "--data", "facts.json", "--date", "2026-10-24")
        self.assertEqual(code, 0)
        result = json.loads(out)
        self.assertEqual(result["markdown_path"], os.path.join("growth-reports", "2026-10-24-pricing-analyzer-acme-test.md"))
        code, out, _ = self.run_main("previous", "--skill", "pricing-analyzer", "--subject", "acme.test")
        self.assertEqual(json.loads(out)["previous_run"]["data"], {"score": 5})
        code, out, _ = self.run_main("path", "--skill", "pricing-analyzer", "--subject", "acme.test",
                                     "--date", "2026-11-01")
        self.assertTrue(json.loads(out)["markdown"].endswith("2026-11-01-pricing-analyzer-acme-test.md"))

    def test_bad_input_exits_2(self):
        code, out, err = self.run_main("save", "--skill", "s", "--subject", "x", "--markdown", "missing.md")
        self.assertEqual(code, 2)
        self.assertEqual(json.loads(out)["status"], "usage_error")
        with open("list.json", "w", encoding="utf-8") as handle:
            handle.write("[1]")
        with open("d.md", "w", encoding="utf-8") as handle:
            handle.write("x")
        code, _, _ = self.run_main("save", "--skill", "s", "--subject", "x", "--markdown", "d.md", "--data", "list.json")
        self.assertEqual(code, 2)
        code, _, _ = self.run_main()
        self.assertEqual(code, 2)

    def test_run_as_a_file_does_not_shadow_stdlib(self):
        # Running .../growthkit/report.py directly puts its folder on sys.path,
        # where http.py and html.py would shadow the standard library.
        script = os.path.join(_paths.SHARED_DIR, "growthkit", "report.py")
        with open("draft.md", "w", encoding="utf-8") as handle:
            handle.write("# Draft\n")
        proc = subprocess.run(
            [sys.executable, script, "save", "--skill", "s", "--subject", "acme.test", "--markdown", "draft.md",
             "--date", "2026-10-24"],
            capture_output=True, text=True, timeout=30,
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertEqual(json.loads(proc.stdout)["status"], "ok")
        self.assertTrue(os.path.exists(os.path.join("growth-reports", "2026-10-24-s-acme-test.md")))

    def test_run_as_module(self):
        env = dict(os.environ, PYTHONPATH=_paths.SHARED_DIR)
        proc = subprocess.run(
            [sys.executable, "-m", "growthkit.report", "path", "--skill", "s", "--subject", "acme.test"],
            capture_output=True, text=True, timeout=30, env=env,
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertIn("growth-reports", json.loads(proc.stdout)["markdown"])


if __name__ == "__main__":
    unittest.main()
